function pointMarker(f){const size=32*(f.style.scale||1);const marker=L.marker(f.coordinates,{title:f.name,icon:pointIcon(f)});marker.bindTooltip(el('span',f.name));marker.on('click',()=>TTI.mergePicking?TTI.toggleMergePoint(f):show(f));return marker;}
function rebuildLayers(){
 const collapsed=new Set([...document.querySelectorAll('.layer-group')].filter(s=>s.querySelector('.layer-group-children').hidden).map(s=>s.dataset.prefix));
 $('layers').replaceChildren();for(const key of [...cableStatuses.map(status=>'Cabluri/'+status),...data.categories]){
 if(!groups.has(key)){groups.set(key,L.featureGroup().addTo(map));enabled.set(key,true);}
 const features=data.features.filter(f=>featureLayers(f).includes(key)),label=el('label',undefined,'layer'),check=el('input');check.type='checkbox';check.checked=enabled.get(key);check.dataset.key=key;check.onchange=()=>toggleCategory(key,check.checked);label.append(check);
 if(key.startsWith('Cabluri/')||(key.startsWith('TTI (1)/Importate/')&&features.some(f=>f.type==='LineString'))){const swatch=el('i',undefined,'line-symbol');const status=key.startsWith('Cabluri/')?key.slice(8):'Importate/'+key.slice(18);swatch.style.background=['Patrulate - traseu diferit fata de documentatie','Segmente documentate eronat'].includes(status)?`radial-gradient(circle, ${cableColors[status]} 2px, transparent 2.5px) left center / 8px 6px repeat-x`:cableColors[status]||TTI.imported?.get(features.find(f=>f.type==='LineString')?.id)?.style.color||'#168d7b';label.append(swatch);}else{const style=TTI.styles.get(key)||TTI.ticketStyle();if(style?.icon){const icon=el('span',undefined,'layer-marker');icon.append(image(style.icon,''));const symbol=statusSymbol(key);if(symbol)icon.append(el('b',symbol,'status-symbol'));label.append(icon);}}
 label.append(el('span',short(key),'layer-name'),el('small',String(features.length)));$('layers').append(label);
 }groupLayerControls();for(const section of document.querySelectorAll('.layer-group'))if(collapsed.has(section.dataset.prefix))section.querySelector('.layer-group-heading button').click();
}
TTI.ticketStyle=function(){const style=[...this.styles.entries()].find(([key])=>short(key).startsWith('Tichete/'))?.[1]||[...this.styles.values()][0];for(const key of this.styles.keys())if(short(key).startsWith('Tichete/'))this.styles.set(key,style);return style;};
TTI.deletePhoto=async function(f,p){if(this.busy||!confirm('Ștergi această fotografie din punct pentru toți utilizatorii?'))return;this.busy=true;try{await this.request('/points/'+f.id+'/photos',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({src:p.src})});if($('viewer').open)$('viewer').close();await this.refresh();show(f);}catch(e){alert(e.message);}finally{this.busy=false;}};
TTI.setupCreation=function(){
 const button=el('button','＋ Adaugă punct pe hartă','add-point'),photoButton=el('button','＋ Punct din fotografie','add-point');$('sidebar').insertBefore(photoButton,$('sidebar').firstChild);$('sidebar').insertBefore(button,photoButton);
 const upload=el('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.hidden=true;photoButton.after(upload);
 let picking=false,draft=null,state=null,epoch=0;
 const clearDraft=()=>{if(draft){map.removeLayer(draft);draft=null;}};
 const cancel=()=>{epoch++;picking=false;state=null;button.textContent='＋ Adaugă punct pe hartă';map.getContainer().classList.remove('placing-point');clearDraft();};this.cancelPointCreation=cancel;
 const newState=(file=null)=>({id:crypto.randomUUID(),photoId:crypto.randomUUID(),file,latitude:null,longitude:null,name:'',address:'',category:'',ticket:'',source:file?'Fotografie încărcată. Verifică poziția înainte de salvare.':'Alege poziția pe hartă.',created:false,confirmed:false});
 const chooseMap=()=>{if(TTI.busy)return;picking=true;button.textContent='Anulează adăugarea';map.getContainer().classList.add('placing-point');$('status').textContent='Click pe hartă pentru poziția punctului nou.';$('details').hidden=true;if(innerWidth<=650)$('sidebar').classList.add('mobile-hidden');};
 button.onclick=()=>{if(this.busy)return;this.cancelCableSelection();if(picking){cancel();return;}cancel();state=newState();chooseMap();};
 photoButton.onclick=()=>{if(this.busy)return;upload.value='';upload.click();};
 this.setupBatchPhotos(upload,photoButton,{begin:cancel,make:newState,open:s=>{cancel();state=s;openForm();}});
 map.on('click',e=>{if(!picking||!state||this.busy)return;picking=false;map.getContainer().classList.remove('placing-point');button.textContent='＋ Adaugă punct pe hartă';Object.assign(state,{latitude:e.latlng.lat,longitude:e.latlng.lng,source:'Poziție aleasă pe hartă.',confirmed:false});openForm();});
 function openForm(){
  const s=state;if(!s)return;selected=null;$('details').hidden=false;const content=$('detail-content');content.replaceChildren(el('h2','Punct nou','detail-title'));
  const form=el('section',undefined,'point-editor'),message=el('p',undefined,'save-status');
  const source=el('p',s.source);source.style.whiteSpace='pre-line';form.append(source);
  if(s.back){const back=el('button','Înapoi la grupuri');back.onclick=()=>{if(!TTI.busy)s.back();};form.append(back);}
  if(s.files?.length>1)form.append(el('p',s.files.length+' fotografii vor fi atașate acestui punct: '+s.files.map(p=>p.file.name).join(', ')));
  if(s.file){const preview=el('img');const objectURL=URL.createObjectURL(s.file);preview.src=objectURL;preview.alt='Fotografia pentru punctul nou';preview.style.cssText='width:100%;max-height:230px;object-fit:contain;border-radius:8px;background:#eef4f3';preview.onload=()=>URL.revokeObjectURL(objectURL);preview.onerror=()=>URL.revokeObjectURL(objectURL);form.append(preview,el('small',s.file.name));
   const ai=el('button','Citește ștampila cu AI');ai.type='button';ai.disabled=s.created;if(!s.batch)form.append(el('p','La apăsare, fotografia este trimisă către OpenAI pentru citirea coordonatelor.'),ai);
   ai.onclick=async()=>{if(TTI.busy||state!==s)return;TTI.busy=true;ai.disabled=true;save.disabled=true;message.textContent='Se citește ștampila…';const token=epoch;try{const result=await TTI.request('/photo-location',{method:'POST',headers:{'Content-Type':s.file.type||'application/octet-stream'},body:s.file});if(token!==epoch)return;s.latitude=result.latitude;s.longitude=result.longitude;s.confirmed=false;if(result.address)s.address=result.address;s.source=[result.latitude===null?'AI nu a identificat coordonate complete. Alege poziția pe hartă sau introdu coordonatele.':result.confidence==='low'?'Citire AI nesigură. Verifică atent coordonatele.':'Coordonate citite din ștampilă cu AI. Verifică poziția.',result.stamp,result.captured_at,result.warning].filter(Boolean).join('\n');openForm();}catch(e){if(token===epoch)message.textContent=e.message;}finally{TTI.busy=false;ai.disabled=false;save.disabled=false;}};
  }
  const makeField=(labelText,key,max)=>{const label=el('label',labelText),input=el('input');input.value=s[key]??'';if(max)input.maxLength=max;input.oninput=()=>{s[key]=input.value;};label.append(input);form.append(label);return input;};
  const latitude=makeField('Latitudine (grade zecimale)','latitude'),longitude=makeField('Longitudine (grade zecimale)','longitude');latitude.inputMode=longitude.inputMode='decimal';
  const marker=()=>{clearDraft();const lat=parseCoordinate(latitude.value),lon=parseCoordinate(longitude.value);if(!validCoords(lat,lon))return;draft=L.marker([lat,lon],{draggable:!s.created}).addTo(map);draft.on('dragend',()=>{const p=draft.getLatLng();s.latitude=p.lat;s.longitude=p.lng;latitude.value=p.lat.toFixed(7);longitude.value=p.lng.toFixed(7);s.confirmed=false;verify.checked=false;});map.setView([lat,lon],Math.max(map.getZoom(),17));};
  const updateCoords=()=>{s.latitude=parseCoordinate(latitude.value);s.longitude=parseCoordinate(longitude.value);s.confirmed=false;verify.checked=false;marker();};latitude.onchange=longitude.onchange=updateCoords;
  const mapPick=el('button','Alege poziția pe hartă');mapPick.type='button';mapPick.onclick=chooseMap;form.append(mapPick);
  const name=makeField('Nume (opțional)','name',200),address=makeField('Adresă (opțional)','address',500);
  const layerLabel=el('label','Strat'),layer=el('select'),placeholder=el('option','Selectează stratul');placeholder.value='';layer.append(placeholder);
  for(const key of data.categories.filter(key=>!short(key).startsWith('Tichete/'))){const option=el('option',short(key));option.value=key;layer.append(option);}const tickets=el('option','Tichete');tickets.value='tickets';layer.append(tickets);layer.value=s.category;layer.setAttribute('aria-label','Strat');layerLabel.append(layer);form.append(layerLabel);
  const ticketLabel=el('label','Număr tichet'),ticket=el('input');ticket.maxLength=100;ticket.placeholder='Ex. 5175126_10773204';ticket.value=s.ticket;ticket.oninput=()=>s.ticket=ticket.value;ticketLabel.append(ticket);ticketLabel.hidden=layer.value!=='tickets';layer.onchange=()=>{s.category=layer.value;ticketLabel.hidden=layer.value!=='tickets';};form.append(ticketLabel);
  const verifyLabel=el('label'),verify=el('input');verify.type='checkbox';verify.checked=s.confirmed;verify.onchange=()=>s.confirmed=verify.checked;verifyLabel.append(verify,document.createTextNode(' Am verificat poziția punctului pe hartă'));form.append(verifyLabel);
  const save=el('button',s.created?'Reîncearcă atașarea fotografiei':'Salvează punctul','save-point'),abort=el('button','Anulează');abort.onclick=()=>{if(TTI.busy)return;cancel();$('details').hidden=true;render();};
  if(s.created)for(const control of [latitude,longitude,mapPick,name,address,layer,ticket,verify])control.disabled=true;
  save.onclick=async()=>{if(TTI.busy||state!==s)return;let category=s.category;const lat=parseCoordinate(latitude.value),lon=parseCoordinate(longitude.value);if(!validCoords(lat,lon)){message.textContent='Alege pe hartă sau introdu coordonate valide.';return;}if(!s.confirmed){message.textContent='Verifică poziția pe hartă și bifează confirmarea.';return;}if(!category){message.textContent='Selectează stratul.';return;}if(category==='tickets'){const number=s.ticket.trim();if(!/^[A-Za-z0-9][A-Za-z0-9_. -]{0,99}$/.test(number)){message.textContent='Introdu numărul tichetului.';return;}category=data.categories.find(k=>short(k)==='Tichete/'+number)||'TTI (1)/Tichete/'+number;}
   TTI.busy=true;save.disabled=true;message.textContent='Se salvează…';try{if(!s.created){await TTI.request('/points',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:s.id,latitude:lat,longitude:lon,name:s.name,address:s.address,category})});s.created=true;}const files=s.files||(s.file?[{file:s.file,photoId:s.photoId}]:[]);for(let i=0;i<files.length;i++){const p=files[i];if(p.uploaded)continue;message.textContent='Se atașează fotografia '+(i+1)+'/'+files.length+'…';await TTI.request('/points/'+s.id+'/photos?uploadId='+p.photoId,{method:'POST',headers:{'Content-Type':p.file.type||'application/octet-stream'},body:p.file});p.uploaded=true;}const id=s.id;cancel();$('search').value='';await TTI.refresh();if(s.onSaved){s.onSaved();}else{const f=TTI.all.find(f=>f.id===id);enabled.set(f.category,true);focus(f);}}catch(e){if(s.created){openForm();$('detail-content').querySelector('.save-status').textContent='Punctul a fost creat. Fotografia nu a fost atașată: '+e.message+' Apasă Reîncearcă.';}else message.textContent=e.message;}finally{TTI.busy=false;save.disabled=false;}
  };
  form.append(save,abort,message);content.append(form);marker();
 }
 function parseCoordinate(value){if(value===null||String(value).trim()==='')return null;const n=Number(String(value).trim().replace(',','.'));return Number.isFinite(n)?n:null;}
 function validCoords(lat,lon){return lat!==null&&lon!==null&&Math.abs(lat)<=90&&Math.abs(lon)<=180;}
 $('close-details').addEventListener('click',cancel);
};
